// Отмена перезагрузки при отправке формы
const form = document.querySelector("form");

form.addEventListener("submit", (event) => {
  event.preventDefault();  // ОСТАНАВЛИВАЕМ перезагрузку!
  console.log("Форма отправлена без перезагрузки");
  // Теперь можно отправить данные через fetch
});

// БАГ: забыли preventDefault — форма перезагрузит страницу
// form.addEventListener("submit", (e) => {
//   console.log("Отправка...");  // выполняется, но...
//   // страница перезагружается!
// });

// ПРАВИЛЬНО: предотвращаем перезагрузку
form.addEventListener("submit", (event) => {
  event.preventDefault();  // стоп!
  console.log("Отправка...");  // теперь выполняется и страница не перезагружается
});

