// События мыши
const box = document.querySelector(".box");
box.addEventListener("click", (e) => {
  console.log("Кординаты:", e.clientX, e.clientY);  // где кликнули
});
box.addEventListener("mouseover", (e) => {
  console.log("Мышь на элементе");
});

// События клавиатуры
document.addEventListener("keydown", (e) => {
  console.log("Нажата:", e.key);
  if (e.key === "Escape") console.log("Выход");
});

const parent = document.querySelector(".parent");
const child = document.querySelector(".child");

parent.addEventListener("click", () => console.log("Родитель"));
child.addEventListener("click", (e) => {
  console.log("Дочерний");
  e.stopPropagation();  // СТОП — родитель не узнает о клике
});

// Клик по child: "Дочерний" — и на этом всё
// Без stopPropagation: "Дочерний" → "Родитель"

const list = document.querySelector(".items");

// Один обработчик на весь список
list.addEventListener("click", (event) => {
  const btn = event.target.closest("button");
  if (!btn) return;  // кликнули не по кнопке
  console.log("Нажата кнопка:", btn.textContent);
});

// Работает даже если кнопки добавлены после загрузки!

const input = document.querySelector("input");

// input — каждый символ
input.addEventListener("input", (e) => {
  console.log("Печатаем:", e.target.value);
});

// change — когда закончили
input.addEventListener("change", (e) => {
  console.log("Финальное значение:", e.target.value);
});

